#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      DATA_TYPE sum = 0.0;
      for (k = 0; k < _PB_NK; ++k) {
        sum += alpha * A[i][k] * B[k][j];
      }
      tmp[i][j] = sum;
    }
  }

  for (i = 0; i < _PB_NI; i++) {
#if defined(__riscv_vector)
    int j_idx = 0;
    vfloat64m1_t v_beta = __riscv_vfmv_v_f_f64m1(beta, __riscv_vsetvlmax_e64m1());
    for (; j_idx < _PB_NL; j_idx += __riscv_vsetvl_e64m1(0)) {
      size_t vl = __riscv_vsetvl_e64m1(_PB_NL - j_idx);
      vfloat64m1_t v_d = __riscv_vle64_v_f64m1(&D[i][j_idx], vl);
      v_d = __riscv_vfmul_vv_f64m1(v_d, v_beta, vl);
      __riscv_vse64_v_f64m1(&D[i][j_idx], v_d, vl);
    }

    for (k = 0; k < _PB_NJ; k++) {
      DATA_TYPE t_val = tmp[i][k];
      int j_idx_inner = 0;
      vfloat64m1_t v_t = __riscv_vfmv_v_f_f64m1(t_val, __riscv_vsetvlmax_e64m1());
      for (; j_idx_inner < _PB_NL; j_idx_inner += __riscv_vsetvl_e64m1(0)) {
        size_t vl = __riscv_vsetvl_e64m1(_PB_NL - j_idx_inner);
        vfloat64m1_t v_c = __riscv_vle64_v_f64m1(&C[k][j_idx_inner], vl);
        vfloat64m1_t v_d = __riscv_vle64_v_f64m1(&D[i][j_idx_inner], vl);
        v_d = __riscv_vfmacc_vv_f64m1(v_d, v_t, v_c, vl);
        __riscv_vse64_v_f64m1(&D[i][j_idx_inner], v_d, vl);
      }
    }
#else
    for (j = 0; j < _PB_NL; j++) {
      D[i][j] *= beta;
    }
    for (k = 0; k < _PB_NJ; k++) {
      DATA_TYPE t_val = tmp[i][k];
      for (j = 0; j < _PB_NL; j++) {
        D[i][j] += t_val * C[k][j];
      }
    }
#endif
  }
#pragma endscop
}

