static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop

  // Matrix Multiplication: E = A * B
  // Reordered loops to (i, k, j) to enable vectorization of the innermost loop
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      E[i][j] = SCALAR_VAL(0.0);
    }
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_val = A[i][k];
      for (j = 0; j < _PB_NJ; j++) {
        E[i][j] += a_val * B[k][j];
      }
    }
  }

  // Matrix Multiplication: F = C * D
  for (i = 0; i < _PB_NJ; i++) {
    for (j = 0; j < _PB_NL; j++) {
      F[i][j] = SCALAR_VAL(0.0);
    }
    for (k = 0; k < _PB_NM; k++) {
      DATA_TYPE c_val = C[i][k];
      for (j = 0; j < _PB_NL; j++) {
        F[i][j] += c_val * D[k][j];
      }
    }
  }

  // Matrix Multiplication: G = E * F
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      G[i][j] = SCALAR_VAL(0.0);
    }
    for (k = 0; k < _PB_NJ; k++) {
      DATA_TYPE e_val = E[i][k];
      for (j = 0; j < _PB_NL; j++) {
        G[i][j] += e_val * F[k][j];
      }
    }
  }
#pragma endscop
}

