static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector)
  // Initialize y to 0
  int j_init = 0;
  while (j_init < n) {
    size_t vl_y = __riscv_vsetvl_e32m1(n - j_init);
    vfloat32m1_t v_zero = __riscv_vfmv_v_f_f32m1(0.0f, vl_y);
    __riscv_vse32_v_f32m1(v_zero, y + j_init, vl_y);
    j_init += vl_y;
  }

  for (i = 0; i < m; i++) {
    // Compute tmp[i] = sum(A[i][j] * x[j])
    vfloat32m1_t v_acc = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvl_e32m1(1));
    int j_dot = 0;
    while (j_dot < n) {
      size_t vl_inner = __riscv_vsetvl_e32m1(n - j_dot);
      vfloat32m1_t v_a = __riscv_vle32_v_f32m1(A[i] + j_dot, vl_inner);
      vfloat32m1_t v_x = __riscv_vle32_v_f32m1(x + j_dot, vl_inner);
      v_acc = __riscv_vfmacc_vv_f32m1(v_acc, v_a, v_x, vl_inner);
      j_dot += vl_inner;
    }

    // Reduction to scalar tmp[i]
    vfloat32m1_t v_zero_red = __riscv_vfmv_v_f_f32m1(0.0f, 1);
    vfloat32m1_t v_red = __riscv_vfredusum_vs_f32m1_f32m1(v_acc, v_zero_red, __riscv_vsetvl_e32m1(n));
    tmp[i] = __riscv_vfmv_f_s_f32m1_f32(v_red);

    // Compute y[j] = y[j] + A[i][j] * tmp[i]
    float t_val = tmp[i];
    int j_sax = 0;
    while (j_sax < n) {
      size_t vl_sax = __riscv_vsetvl_e32m1(n - j_sax);
      vfloat32m1_t v_y = __riscv_vle32_v_f32m1(y + j_sax, vl_sax);
      vfloat32m1_t v_a = __riscv_vle32_v_f32m1(A[i] + j_sax, vl_sax);
      v_y = __riscv_vfmacc_vf_f32m1(v_y, t_val, v_a, vl_sax);
      __riscv_vse32_v_f32m1(v_y, y + j_sax, vl_sax);
      j_sax += vl_sax;
    }
  }
#else
  for (i = 0; i < n; i++)
    y[i] = 0;
  for (i = 0; i < m; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < n; j++)
	tmp[i] = tmp[i] + A[i][j] * x[j];
      for (j = 0; j < n; j++)
	y[j] = y[j] + A[i][j] * tmp[i];
    }
#endif
#pragma endscop
}

