static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE ri = r[i];
      DATA_TYPE qi_scalar = SCALAR_VAL(0.0);

#if defined(__riscv_vector)
      int j_vec = 0;
      vfloat64m1_t v_qi = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvl_e64m1(0));

      while (j_vec < _PB_M) {
        size_t vl = __riscv_vsetvl_e64m1(_PB_M - j_vec);
        vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[i][j_vec], vl);

        // s[j] = s[j] + ri * A[i][j]
        vfloat64m1_t v_s = __riscv_vle64_v_f64m1(&s[j_vec], vl);
        v_s = __riscv_vfmacc_vf_f64m1(v_s, ri, v_a, vl);
        __riscv_vse64_v_f64m1(&s[j_vec], v_s, vl);

        // qi = qi + A[i][j] * p[j]
        vfloat64m1_t v_p = __riscv_vle64_v_f64m1(&p[j_vec], vl);
        v_qi = __riscv_vfmacc_vv_f64m1(v_qi, v_a, v_p, vl);

        j_vec += vl;
      }

      // Reduction for qi
      vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvl_e64m1(1));
      vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_qi, v_zero, __riscv_vsetvl_e64m1(0));
      qi_scalar = __riscv_vfmv_f_s_f64m1_f64(v_res);
#else
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + ri * A[i][j];
	  qi_scalar = qi_scalar + A[i][j] * p[j];
	}
#endif
      q[i] = qi_scalar;
    }
#pragma endscop
}

