static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        DATA_TYPE sum = 0;
#if defined(__riscv_vector)
        int vl;
        int k_idx = 0;
        vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

        while (k_idx < j) {
            vl = __riscv_vsetvl_e64m1(j - k_idx);
            vfloat64m1_t v_aik = __riscv_vle64_v_f64m1(&A[i][k_idx], vl);
            vfloat64m1_t v_ajk = __riscv_vle64_v_f64m1(&A[j][k_idx], vl);
            v_sum = __riscv_vfmacc_vv_f64m1(v_sum, v_aik, v_ajk, vl);
            k_idx += vl;
        }

        // Use vfredusum.vs intrinsic correctly. 
        // The intrinsic name in many RVV toolchains is __riscv_vfredusum_vs_f64m1
        // but if it's missing, we can use a loop or check the specific intrinsic name.
        // Given the error, we'll use a more compatible approach for reduction.
        DATA_TYPE temp_sum = 0;
        vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_m1(v_sum, v_zero, __riscv_vsetvlmax_e64m1());
        __riscv_vse64_v_f64m1(&temp_sum, v_res, 1);
        sum = temp_sum;
#else
        for (k = 0; k < j; k++) {
           sum += A[i][k] * A[j][k];
        }
#endif
        A[i][j] -= sum;
        A[i][j] /= A[j][j];
     }

     DATA_TYPE diag_sum = 0;
#if defined(__riscv_vector)
        int vl;
        int k_idx = 0;
        vfloat64m1_t v_diag_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
        while (k_idx < i) {
            vl = __riscv_vsetvl_e64m1(i - k_idx);
            vfloat64m1_t v_aik = __riscv_vle64_v_f64m1(&A[i][k_idx], vl);
            v_diag_sum = __riscv_vfmacc_vv_f64m1(v_diag_sum, v_aik, v_aik, vl);
            k_idx += vl;
        }
        DATA_TYPE temp_diag_sum = 0;
        vfloat64m1_t v_zero_diag = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vfloat64m1_t v_res_diag = __riscv_vfredusum_vs_f64m1_m1(v_diag_sum, v_zero_diag, __riscv_vsetvlmax_e64m1());
        __riscv_vse64_v_f64m1(&temp_diag_sum, v_res_diag, 1);
        diag_sum = temp_diag_sum;
#else
        for (k = 0; k < i; k++) {
           diag_sum += A[i][k] * A[i][k];
        }
#endif
     A[i][i] -= diag_sum;
     A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

