static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int i_vec = 0;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        size_t vl;
        vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        for (; i_vec < _PB_N; i_vec += vl) {
          vl = __riscv_vsetvl_e32m1( _PB_N - i_vec);
          vfloat32m1_t v_data = __riscv_vlse32_v_f32m1(&data[i_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_data, vl);
        }
        sum = __riscv_vfredusum_vs_f32m1(__riscv_vfmv_v_f_f32m1(0.0f, 1), v_sum, __riscv_vsetvlmax_e32m1());
      } else {
        for (i = 0; i < _PB_N; i++) sum += data[i][j];
      }
#else
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
#endif
      mean[j] = sum / float_n;
    }

   for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE s_sum = SCALAR_VAL(0.0);
      int i_vec = 0;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        size_t vl;
        vfloat32m1_t v_s_sum = __riscv_vfmv_v_f_f32m1(0.0f, 1);
        vfloat32m1_t v_mean = __riscv_vfmv_v_f_f32m1((float)mean[j], 1);
        for (; i_vec < _PB_N; i_vec += vl) {
          vl = __riscv_vsetvl_e32m1( _PB_N - i_vec);
          vfloat32m1_t v_data = __riscv_vlse32_v_f32m1(&data[i_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
          vfloat32m1_t v_diff = __riscv_vfsub_vv_f32m1(v_data, v_mean, vl);
          v_s_sum = __riscv_vfmac_vv_f32m1(v_s_sum, v_diff, v_diff, vl);
        }
        s_sum = __riscv_vfredusum_vs_f32m1(__riscv_vfmv_v_f_f32m1(0.0f, 1), v_s_sum, __riscv_vsetvlmax_e32m1());
      } else {
        for (i = 0; i < _PB_N; i++)
          s_sum += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      }
#else
      for (i = 0; i < _PB_N; i++)
        s_sum += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
#endif
      stddev[j] = SQRT_FUN(s_sum / float_n);
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }

  DATA_TYPE inv_sqrt_n = SCALAR_VAL(1.0) / SQRT_FUN(float_n);
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE scale = inv_sqrt_n / stddev[j];
      int i_vec = 0;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        size_t vl;
        vfloat32m1_t v_scale = __riscv_vfmv_v_f_f32m1((float)scale, 1);
        vfloat32m1_t v_mean_j = __riscv_vfmv_v_f_f32m1((float)mean[j], 1);
        for (; i_vec < _PB_N; i_vec += vl) {
          vl = __riscv_vsetvl_e32m1( _PB_N - i_vec);
          vfloat32m1_t v_data = __riscv_vlse32_v_f32m1(&data[i_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
          vfloat32m1_t v_res = __riscv_vfsub_vv_f32m1(v_data, v_mean_j, vl);
          v_res = __riscv_vfmul_vv_f32m1(v_res, v_scale, vl);
          __riscv_vse32_v_f32m1(&data[i_vec][j], v_res, _PB_M * sizeof(DATA_TYPE), vl);
        }
      } else {
        for (i = 0; i < _PB_N; i++) {
          data[i][j] -= mean[j];
          data[i][j] *= scale;
        }
      }
#else
      for (i = 0; i < _PB_N; i++) {
        data[i][j] -= mean[j];
        data[i][j] *= scale;
      }
#endif
    }

  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          int k_vec = 0;
#if defined(__riscv_vector)
          if (sizeof(DATA_TYPE) == 4) {
            size_t vl;
            vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, 1);
            for (; k_vec < _PB_N; k_vec += vl) {
              vl = __riscv_vsetvl_e32m1( _PB_N - k_vec);
              vfloat32m1_t v_data_i = __riscv_vlse32_v_f32m1(&data[k_vec][i], _PB_M * sizeof(DATA_TYPE), vl);
              vfloat32m1_t v_data_j = __riscv_vlse32_v_f32m1(&data[k_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
              v_sum = __riscv_vfmac_vv_f32m1(v_sum, v_data_i, v_data_j, vl);
            }
            sum = __riscv_vfredusum_vs_f32m1(__riscv_vfmv_v_f_f32m1(0.0f, 1), v_sum, __riscv_vsetvlmax_e32m1());
          } else {
            for (k = 0; k < _PB_N; k++)
              sum += (data[k][i] * data[k][j]);
          }
#else
          for (k = 0; k < _PB_N; k++)
            sum += (data[k][i] * data[k][j]);
#endif
          corr[i][j] = sum;
          corr[j][i] = sum;
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop
}

