static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      DATA_TYPE sum = SCALAR_VAL(0.0);
      int i_vec;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        int vl;
        vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());
        for (i_vec = 0; i_vec < _PB_N; ) {
          vl = __riscv_vsetvl_e32m1(_PB_N - i_vec);
          v_sum = __riscv_vfmacc_vf_f32m1(v_sum, 1.0f, __riscv_vlse32_v_f32m1((float*)&data[i_vec][j], _PB_M * sizeof(DATA_TYPE), vl), vl);
          i_vec += vl;
        }
        sum = __riscv_vfredusum_vs_f32m1_f32(__riscv_vfmv_v_f_f32m1(0.0f, 1), v_sum, __riscv_vsetvlmax_e32m1());
      } else if (sizeof(DATA_TYPE) == 8) {
        int vl;
        vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
        for (i_vec = 0; i_vec < _PB_N; ) {
          vl = __riscv_vsetvl_e64m1(_PB_N - i_vec);
          v_sum = __riscv_vfmacc_vf_f64m1(v_sum, 1.0, __riscv_vlse64_v_f64m1((double*)&data[i_vec][j], _PB_M * sizeof(DATA_TYPE), vl), vl);
          i_vec += vl;
        }
        sum = __riscv_vfredusum_vs_f64m1_f64(__riscv_vfmv_v_f_f64m1(0.0, 1), v_sum, __riscv_vsetvlmax_e64m1());
      } else {
        for (i = 0; i < _PB_N; i++) sum += data[i][j];
      }
#else
      for (i = 0; i < _PB_N; i++)
        sum += data[i][j];
#endif
      mean[j] = sum / float_n;
    }

  for (i = 0; i < _PB_N; i++) {
    int j_vec;
#if defined(__riscv_vector)
    if (sizeof(DATA_TYPE) == 4) {
      int vl;
      for (j_vec = 0; j_vec < _PB_M; ) {
        vl = __riscv_vsetvl_e32m1(_PB_M - j_vec);
        vfloat32m1_t v_mean = __riscv_vle32_v_f32m1((float*)&mean[j_vec], vl);
        vfloat32m1_t v_data = __riscv_vle32_v_f32m1((float*)&data[i][j_vec], vl);
        vfloat32m1_t v_res = __riscv_vfsub_vv_f32m1(v_data, v_mean, vl);
        __riscv_vse32_v_f32m1((float*)&data[i][j_vec], v_res, vl);
        j_vec += vl;
      }
    } else if (sizeof(DATA_TYPE) == 8) {
      int vl;
      for (j_vec = 0; j_vec < _PB_M; ) {
        vl = __riscv_vsetvl_e64m1(_PB_M - j_vec);
        vfloat64m1_t v_mean = __riscv_vle64_v_f64m1((double*)&mean[j_vec], vl);
        vfloat64m1_t v_data = __riscv_vle64_v_f64m1((double*)&data[i][j_vec], vl);
        vfloat64m1_t v_res = __riscv_vfsub_vv_f64m1(v_data, v_mean, vl);
        __riscv_vse64_v_f64m1((double*)&data[i][j_vec], v_res, vl);
        j_vec += vl;
      }
    } else {
      for (j = 0; j < _PB_M; j++) data[i][j] -= mean[j];
    }
#else
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];
#endif
  }

  DATA_TYPE denom = float_n - SCALAR_VAL(1.0);
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        DATA_TYPE sum = SCALAR_VAL(0.0);
        int k_vec;
#if defined(__riscv_vector)
        if (sizeof(DATA_TYPE) == 4) {
          int vl;
          vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, __riscv_vsetvlmax_e32m1());
          for (k_vec = 0; k_vec < _PB_N; ) {
            vl = __riscv_vsetvl_e32m1(_PB_N - k_vec);
            vfloat32m1_t v_data_i = __riscv_vlse32_v_f32m1((float*)&data[k_vec][i], _PB_M * sizeof(DATA_TYPE), vl);
            vfloat32m1_t v_data_j = __riscv_vlse32_v_f32m1((float*)&data[k_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
            v_sum = __riscv_vfmacc_vv_f32m1(v_sum, v_data_i, v_data_j, vl);
            k_vec += vl;
          }
          sum = __riscv_vfredusum_vs_f32m1_f32(__riscv_vfmv_v_f_f32m1(0.0f, 1), v_sum, __riscv_vsetvlmax_e32m1());
        } else if (sizeof(DATA_TYPE) == 8) {
          int vl;
          vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
          for (k_vec = 0; k_vec < _PB_N; ) {
            vl = __riscv_vsetvl_e64m1(_PB_N - k_vec);
            vfloat64m1_t v_data_i = __riscv_vlse64_v_f64m1((double*)&data[k_vec][i], _PB_M * sizeof(DATA_TYPE), vl);
            vfloat64m1_t v_data_j = __riscv_vlse64_v_f64m1((double*)&data[k_vec][j], _PB_M * sizeof(DATA_TYPE), vl);
            v_sum = __riscv_vfmacc_vv_f64m1(v_sum, v_data_i, v_data_j, vl);
            k_vec += vl;
          }
          sum = __riscv_vfredusum_vs_f64m1_f64(__riscv_vfmv_v_f_f64m1(0.0, 1), v_sum, __riscv_vsetvlmax_e64m1());
        } else {
          for (k = 0; k < _PB_N; k++) sum += data[k][i] * data[k][j];
        }
#else
        for (k = 0; k < _PB_N; k++)
          sum += data[k][i] * data[k][j];
#endif
        cov[i][j] = sum / denom;
        cov[j][i] = cov[i][j];
      }
#pragma endscop
}

