#include <riscv_vector.h>
#endif

void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      // Initialize sum to 0
      for (p = 0; p < _PB_NP; p++) {
        sum[p] = SCALAR_VAL(0.0);
      }

#if defined(__riscv_vector)
      // The operation is: sum[p] = sum_{s=0 to NP-1} (A[r][q][s] * C4[s][p])
      // Based on the error, DATA_TYPE is double. We use f64 vector intrinsics.
      for (s = 0; s < _PB_NP; s++) {
        double a_val = (double)A[r][q][s];
        int p_idx = 0;
        size_t vl;

        while (p_idx < _PB_NP) {
          vl = __riscv_vsetvl_e64m1(_PB_NP - p_idx);

          // Load C4[s][p...p+vl-1]
          vfloat64m1_t v_c = __riscv_vle64_v_f64m1(&C4[s][p_idx], vl);

          // Load sum[p...p+vl-1]
          vfloat64m1_t v_s = __riscv_vle64_v_f64m1(&sum[p_idx], vl);

          // sum[p] += a_val * C4[s][p]
          // Use vfmacc.vf: v_s = v_s + (a_val * v_c)
          v_s = __riscv_vfmacc_vf_f64m1(v_s, a_val, v_c, vl);

          // Store back to sum
          __riscv_vse64_v_f64m1(&sum[p_idx], v_s, vl);

          p_idx += vl;
        }
      }
#else
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_val = A[r][q][s];
        for (p = 0; p < _PB_NP; p++) {
          sum[p] += a_val * C4[s][p];
        }
      }
#endif
      // Copy sum back to A[r][q][p]
      for (p = 0; p < _PB_NP; p++) {
        A[r][q][p] = sum[p];
      }
    }
  }
#pragma endscop
}

