static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (SCALAR_VAL(1.0) - alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   // Vectorized dot product for sum
   int i_sum = 0;
#if defined(__riscv_vector)
   size_t vl_sum;
   vfloat64m1_t v_sum_vec = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

   while (i_sum < k) {
     vl_sum = __riscv_vsetvl_e64m1(k - i_sum);
     // r[k-i-1] is accessed with stride -1
     vfloat64m1_t vr = __riscv_vlse64_v_f64m1(&r[k - i_sum - 1], -sizeof(DATA_TYPE), vl_sum);
     vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[i_sum], vl_sum);
     v_sum_vec = __riscv_vfmacc_vv_f64m1(v_sum_vec, vr, vy, vl_sum);
     i_sum += vl_sum;
   }
   vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
   vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_sum_vec, v_zero, __riscv_vsetvlmax_e64m1());
   sum = __riscv_vfmv_f_s_f64m1_f64(v_res);
#else
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
#endif

   alpha = - (r[k] + sum)/beta;

   // Vectorized update for z and y
   int i_upd = 0;
#if defined(__riscv_vector)
   size_t vl_upd;
   while (i_upd < k) {
     vl_upd = __riscv_vsetvl_e64m1(k - i_upd);
     vfloat64m1_t vy_fwd = __riscv_vle64_v_f64m1(&y[i_upd], vl_upd);
     vfloat64m1_t vy_rev = __riscv_vlse64_v_f64m1(&y[k - i_upd - 1], -sizeof(DATA_TYPE), vl_upd);
     // z[i] = y[i] + alpha * y[k-i-1]
     vfloat64m1_t vz = __riscv_vfmacc_vf_f64m1(vy_fwd, alpha, vy_rev, vl_upd);
     __riscv_vse64_v_f64m1(&z[i_upd], vz, vl_upd);
     i_upd += vl_upd;
   }

   // Copy z back to y. We can optimize this by using the same loop as above 
   // but since z is a temporary array and we need to maintain the logic, 
   // we can merge the store to y directly if we are careful.
   // However, to ensure correctness with the original logic:
   i_upd = 0;
   while (i_upd < k) {
     vl_upd = __riscv_vsetvl_e64m1(k - i_upd);
     vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[i_upd], vl_upd);
     __riscv_vse64_v_f64m1(&y[i_upd], vz, vl_upd);
     i_upd += vl_upd;
   }
#else
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
#endif
   y[k] = alpha;
 }
#pragma endscop

}

