#include <riscv_vector.h>
#endif

static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      DATA_TYPE fict_val = _fict_[t];
#if defined(__riscv_vector)
      // The error indicates DATA_TYPE is double, but we used e32m1 (float).
      // We must use e64m1 for double precision.
      int vl;
      for (j = 0; j < _PB_NY; j += vl) {
        vl = __riscv_vsetvl_e64m1(_PB_NY - j);
        vfloat64m1_t v_fict = __riscv_vfmv_v_f_f64m1(vl, (double)fict_val);
        __riscv_vse64_v_f64m1(&ey[0][j], v_fict, vl);
      }

      double c1 = (double)SCALAR_VAL(0.5);
      for (i = 1; i < _PB_NX; i++) {
        for (j = 0; j < _PB_NY; j += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_NY - j);
          vfloat64m1_t v_hz_i = __riscv_vle64_v_f64m1(&hz[i][j], vl);
          vfloat64m1_t v_hz_im1 = __riscv_vle64_v_f64m1(&hz[i-1][j], vl);
          vfloat64m1_t v_ey = __riscv_vle64_v_f64m1(&ey[i][j], vl);
          vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(vl, v_hz_i, v_hz_im1);
          vfloat64m1_t v_final = __riscv_vfnmsub_vf_f64m1(vl, v_diff, c1, v_ey, 0.0);
          __riscv_vse64_v_f64m1(&ey[i][j], v_final, vl);
        }
      }

      for (i = 0; i < _PB_NX; i++) {
        for (j = 1; j < _PB_NY; j += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_NY - j);
          vfloat64m1_t v_hz_j = __riscv_vle64_v_f64m1(&hz[i][j], vl);
          vfloat64m1_t v_hz_jm1 = __riscv_vle64_v_f64m1(&hz[i][j-1], vl);
          vfloat64m1_t v_ex = __riscv_vle64_v_f64m1(&ex[i][j], vl);
          vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(vl, v_hz_j, v_hz_jm1);
          vfloat64m1_t v_final = __riscv_vfnmsub_vf_f64m1(vl, v_diff, c1, v_ex, 0.0);
          __riscv_vse64_v_f64m1(&ex[i][j], v_final, vl);
        }
      }

      double c2 = (double)SCALAR_VAL(0.7);
      for (i = 0; i < _PB_NX - 1; i++) {
        for (j = 0; j < _PB_NY - 1; j += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_NY - 1 - j);
          vfloat64m1_t v_ex_jp1 = __riscv_vle64_v_f64m1(&ex[i][j+1], vl);
          vfloat64m1_t v_ex_j = __riscv_vle64_v_f64m1(&ex[i][j], vl);
          vfloat64m1_t v_ey_ip1 = __riscv_vle64_v_f64m1(&ey[i+1][j], vl);
          vfloat64m1_t v_ey_i = __riscv_vle64_v_f64m1(&ey[i][j], vl);
          vfloat64m1_t v_hz = __riscv_vle64_v_f64m1(&hz[i][j], vl);

          vfloat64m1_t v_term1 = __riscv_vfsub_vv_f64m1(vl, v_ex_jp1, v_ex_j);
          vfloat64m1_t v_term2 = __riscv_vfsub_vv_f64m1(vl, v_ey_ip1, v_ey_i);
          vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(vl, v_term1, v_term2);
          vfloat64m1_t v_final = __riscv_vfnmsub_vf_f64m1(vl, v_sum, c2, v_hz, 0.0);
          __riscv_vse64_v_f64m1(&hz[i][j], v_final, vl);
        }
      }
#else
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = fict_val;
      for (i = 1; i < _PB_NX; i++)
	for (j = 0; j < _PB_NY; j++)
	  ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
      for (i = 0; i < _PB_NX; i++)
	for (j = 1; j < _PB_NY; j++)
	  ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
      for (i = 0; i < _PB_NX - 1; i++)
	for (j = 0; j < _PB_NY - 1; j++)
	  hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
#endif
    }

#pragma endscop
}

