static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
        {
          DATA_TYPE path_ik = path[i][k];

          #if defined(__riscv_vector)
          int j_vec = 0;
          size_t vl;

          for (; j_vec < _PB_N; j_vec += vl) {
            vl = __riscv_vsetvl_e32m1(_PB_N - j_vec);
            vint32m1_t v_path_kj = __riscv_vle32_v_i32m1(&path[k][j_vec], vl);
            vint32m1_t v_path_ij = __riscv_vle32_v_i32m1(&path[i][j_vec], vl);

            // path[i][j] = min(path[i][j], path[i][k] + path[k][j])
            vint32m1_t v_sum = __riscv_vadd_vx_i32m1(v_path_kj, path_ik, vl);
            vint32m1_t v_min = __riscv_vmin_vv_i32m1(v_path_ij, v_sum, vl);

            __riscv_vse32_v_i32m1(&path[i][j_vec], v_min, vl);
          }
          #else
          for (j = 0; j < _PB_N; j++) {
            DATA_TYPE sum = path_ik + path[k][j];
            if (sum < path[i][j]) {
              path[i][j] = sum;
            }
          }
          #endif
        }
    }
#pragma endscop

}

