static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    // Initialize C[i][j] = C[i][j] * beta
    int j_init = 0;
#if defined(__riscv_vector)
    if (sizeof(DATA_TYPE) == 4) {
      size_t vl_init;
      vfloat32m1_t v_beta = __riscv_vfmv_v_f_f32m1(__riscv_vsetvlmax_e32m1(), (float)beta);
      while (j_init < _PB_NJ) {
        vl_init = __riscv_vsetvl_e32m1(_PB_NJ - j_init);
        vfloat32m1_t v_c = __riscv_vle32_v_f32m1((float*)&C[i][j_init], vl_init);
        v_c = __riscv_vfmul_vv_f32m1(v_c, v_beta, vl_init);
        __riscv_vse32_v_f32m1((float*)&C[i][j_init], v_c, vl_init);
        j_init += vl_init;
      }
    } else if (sizeof(DATA_TYPE) == 8) {
      size_t vl_init;
      vfloat64m1_t v_beta = __riscv_vfmv_v_f_f64m1(__riscv_vsetvlmax_e64m1(), (double)beta);
      while (j_init < _PB_NJ) {
        vl_init = __riscv_vsetvl_e64m1(_PB_NJ - j_init);
        vfloat64m1_t v_c = __riscv_vle64_v_f64m1((double*)&C[i][j_init], vl_init);
        v_c = __riscv_vfmul_vv_f64m1(v_c, v_beta, vl_init);
        __riscv_vse64_v_f64m1((double*)&C[i][j_init], v_c, vl_init);
        j_init += vl_init;
      }
    } else {
      for (j = 0; j < _PB_NJ; j++) C[i][j] *= beta;
    }
#else
    for (j = 0; j < _PB_NJ; j++)
      C[i][j] *= beta;
#endif

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE a_ik = A[i][k];
      int j_gemm = 0;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        size_t vl_gemm;
        vfloat32m1_t v_alpha_aik = __riscv_vfmv_v_f_f32m1(__riscv_vsetvlmax_e32m1(), (float)(alpha * a_ik));
        while (j_gemm < _PB_NJ) {
          vl_gemm = __riscv_vsetvl_e32m1(_PB_NJ - j_gemm);
          vfloat32m1_t v_b = __riscv_vle32_v_f32m1((float*)&B[k][j_gemm], vl_gemm);
          vfloat32m1_t v_c = __riscv_vle32_v_f32m1((float*)&C[i][j_gemm], vl_gemm);
          v_c = __riscv_vfmacc_vv_f32m1(v_c, v_alpha_aik, v_b, vl_gemm);
          __riscv_vse32_v_f32m1((float*)&C[i][j_gemm], v_c, vl_gemm);
          j_gemm += vl_gemm;
        }
      } else if (sizeof(DATA_TYPE) == 8) {
        size_t vl_gemm;
        vfloat64m1_t v_alpha_aik = __riscv_vfmv_v_f_f64m1(__riscv_vsetvlmax_e64m1(), (double)(alpha * a_ik));
        while (j_gemm < _PB_NJ) {
          vl_gemm = __riscv_vsetvl_e64m1(_PB_NJ - j_gemm);
          vfloat64m1_t v_b = __riscv_vle64_v_f64m1((double*)&B[k][j_gemm], vl_gemm);
          vfloat64m1_t v_c = __riscv_vle64_v_f64m1((double*)&C[i][j_gemm], vl_gemm);
          v_c = __riscv_vfmacc_vv_f64m1(v_c, v_alpha_aik, v_b, vl_gemm);
          __riscv_vse64_v_f64m1((double*)&C[i][j_gemm], v_c, vl_gemm);
          j_gemm += vl_gemm;
        }
      } else {
        for (j = 0; j < _PB_NJ; j++) C[i][j] += alpha * a_ik * B[k][j];
      }
#else
      for (j = 0; j < _PB_NJ; j++)
        C[i][j] += alpha * a_ik * B[k][j];
#endif
    }
  }
#pragma endscop
}

