static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1_val = u1[i];
    DATA_TYPE u2_val = u2[i];
#if defined(__riscv_vector) && (sizeof(DATA_TYPE) == 4)
    int j_idx = 0;
    size_t vl;
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e32m1(_PB_N - j_idx);
      vfloat32m1_t v_v1 = __riscv_vle32_v_f32m1(&v1[j_idx], vl);
      vfloat32m1_t v_v2 = __riscv_vle32_v_f32m1(&v2[j_idx], vl);
      vfloat32m1_t v_A = __riscv_vle32_v_f32m1(&A[i][j_idx], vl);

      vfloat32m1_t v_u1_vec = __riscv_vfmv_v_f_f32m1(u1_val, vl);
      vfloat32m1_t v_u2_vec = __riscv_vfmv_v_f_f32m1(u2_val, vl);

      v_A = __riscv_vfmacc_f32m1(v_A, v_u1_vec, v_v1, vl);
      v_A = __riscv_vfmacc_f32m1(v_A, v_u2_vec, v_v2, vl);
      __riscv_vse32_v_f32m1(&A[i][j_idx], v_A, vl);
    }
#elif defined(__riscv_vector) && (sizeof(DATA_TYPE) == 8)
    int j_idx = 0;
    size_t vl;
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j_idx);
      vfloat64m1_t v_v1 = __riscv_vle64_v_f64m1(&v1[j_idx], vl);
      vfloat64m1_t v_v2 = __riscv_vle64_v_f64m1(&v2[j_idx], vl);
      vfloat64m1_t v_A = __riscv_vle64_v_f64m1(&A[i][j_idx], vl);

      vfloat64m1_t v_u1_vec = __riscv_vfmv_v_f_f64m1(u1_val, vl);
      vfloat64m1_t v_u2_vec = __riscv_vfmv_v_f_f64m1(u2_val, vl);

      v_A = __riscv_vfmacc_f64m1(v_A, v_u1_vec, v_v1, vl);
      v_A = __riscv_vfmacc_f64m1(v_A, v_u2_vec, v_v2, vl);
      __riscv_vse64_v_f64m1(&A[i][j_idx], v_A, vl);
    }
#else
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + u1_val * v1[j] + u2_val * v2[j];
#endif
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = 0;
#if defined(__riscv_vector) && (sizeof(DATA_TYPE) == 4)
    int j_idx = 0;
    size_t vl;
    vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, 1); 
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e32m1(_PB_N - j_idx);
      vfloat32m1_t v_A = __riscv_vlse32_v_f32m1(&A[j_idx][i], _PB_N * sizeof(DATA_TYPE), vl);
      vfloat32m1_t v_y = __riscv_vle32_v_f32m1(&y[j_idx], vl);
      v_sum = __riscv_vfmacc_f32m1(v_sum, v_A, v_y, vl);
    }
    sum = __riscv_vfredusum_f32m1(v_sum, 0.0f, 1);
#elif defined(__riscv_vector) && (sizeof(DATA_TYPE) == 8)
    int j_idx = 0;
    size_t vl;
    vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, 1); 
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j_idx);
      vfloat64m1_t v_A = __riscv_vlse64_v_f64m1(&A[j_idx][i], _PB_N * sizeof(DATA_TYPE), vl);
      vfloat64m1_t v_y = __riscv_vle64_v_f64m1(&y[j_idx], vl);
      v_sum = __riscv_vfmacc_f64m1(v_sum, v_A, v_y, vl);
    }
    sum = __riscv_vfredusum_f64m1(v_sum, 0.0, 1);
#else
    for (j = 0; j < _PB_N; j++)
      sum += A[j][i] * y[j];
#endif
    x[i] = x[i] + beta * sum;
  }

#if defined(__riscv_vector) && (sizeof(DATA_TYPE) == 4)
  int i_idx = 0;
  size_t vl;
  for (; i_idx < _PB_N; i_idx += vl) {
    vl = __riscv_vsetvl_e32m1(_PB_N - i_idx);
    vfloat32m1_t v_x = __riscv_vle32_v_f32m1(&x[i_idx], vl);
    vfloat32m1_t v_z = __riscv_vle32_v_f32m1(&z[i_idx], vl);
    v_x = __riscv_vfadd_f32m1(v_x, v_z, vl);
    __riscv_vse32_v_f32m1(&x[i_idx], v_x, vl);
  }
#elif defined(__riscv_vector) && (sizeof(DATA_TYPE) == 8)
  int i_idx = 0;
  size_t vl;
  for (; i_idx < _PB_N; i_idx += vl) {
    vl = __riscv_vsetvl_e64m1(_PB_N - i_idx);
    vfloat64m1_t v_x = __riscv_vle64_v_f64m1(&x[i_idx], vl);
    vfloat64m1_t v_z = __riscv_vle64_v_f64m1(&z[i_idx], vl);
    v_x = __riscv_vfadd_f64m1(v_x, v_z, vl);
    __riscv_vse64_v_f64m1(&x[i_idx], v_x, vl);
  }
#else
  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];
#endif

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE sum = 0;
#if defined(__riscv_vector) && (sizeof(DATA_TYPE) == 4)
    int j_idx = 0;
    size_t vl;
    vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, 1);
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e32m1(_PB_N - j_idx);
      vfloat32m1_t v_A = __riscv_vle32_v_f32m1(&A[i][j_idx], vl);
      vfloat32m1_t v_x = __riscv_vle32_v_f32m1(&x[j_idx], vl);
      v_sum = __riscv_vfmacc_f32m1(v_sum, v_A, v_x, vl);
    }
    sum = __riscv_vfredusum_f32m1(v_sum, 0.0f, 1);
#elif defined(__riscv_vector) && (sizeof(DATA_TYPE) == 8)
    int j_idx = 0;
    size_t vl;
    vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, 1);
    for (; j_idx < _PB_N; j_idx += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j_idx);
      vfloat64m1_t v_A = __riscv_vle64_v_f64m1(&A[i][j_idx], vl);
      vfloat64m1_t v_x = __riscv_vle64_v_f64m1(&x[j_idx], vl);
      v_sum = __riscv_vfmacc_f64m1(v_sum, v_A, v_x, vl);
    }
    sum = __riscv_vfredusum_f64m1(v_sum, 0.0, 1);
#else
    for (j = 0; j < _PB_N; j++)
      sum += A[i][j] * x[j];
#endif
    w[i] = w[i] + alpha * sum;
  }

#pragma endscop
}

