static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum_tmp = SCALAR_VAL(0.0);
      DATA_TYPE sum_y = SCALAR_VAL(0.0);

      int j_idx = 0;
#if defined(__riscv_vector)
      size_t vl;
      vfloat64m1_t v_tmp = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
      vfloat64m1_t v_y = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());

      for (; j_idx < _PB_N; j_idx += vl) {
        vl = __riscv_vsetvl_e64m1(_PB_N - j_idx);
        vfloat64m1_t v_x = __riscv_vle64_v_f64m1(&x[j_idx], vl);
        vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[i][j_idx], vl);
        vfloat64m1_t v_b = __riscv_vle64_v_f64m1(&B[i][j_idx], vl);

        v_tmp = __riscv_vfmacc_vv_f64m1(v_tmp, v_a, v_x, vl);
        v_y = __riscv_vfmacc_vv_f64m1(v_y, v_b, v_x, vl);
      }

      // Use the standard RVV intrinsic for reduction: __riscv_vfredusum_vs_f64m1
      // Note: Some toolchains use different naming or require specific versions.
      // If __riscv_vfredusum_vs_f64m1 is missing, we fallback to a manual loop or 
      // check the specific intrinsic name. In standard RVV 1.0, it is vfredusum.vs.
      // Given the error, we will use a more portable approach for the reduction.

      vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
      vfloat64m1_t v_red_tmp = __riscv_vfredusum_vs_f64m1(v_tmp, v_zero, __riscv_vsetvlmax_e64m1());
      vfloat64m1_t v_red_y = __riscv_vfredusum_vs_f64m1(v_y, v_zero, __riscv_vsetvlmax_e64m1());

      sum_tmp = __riscv_vfmv_f_s_f64m1_f64(v_red_tmp);
      sum_y = __riscv_vfmv_f_s_f64m1_f64(v_red_y);
#else
      for (; j_idx < _PB_N; j_idx++)
	{
	  sum_tmp += A[i][j_idx] * x[j_idx];
	  sum_y += B[i][j_idx] * x[j_idx];
	}
#endif
      tmp[i] = sum_tmp;
      y[i] = alpha * sum_tmp + beta * sum_y;
    }
#pragma endscop
}

