static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);

      #if defined(__riscv_vector)
      size_t vl;
      vfloat64m1_t v_nrm = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
      for (i = 0; i < _PB_M; i += __riscv_vsetvlmax_e64m1()) {
        vl = __riscv_vsetvl_e64m1(_PB_M - i);
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][k], vl);
        v_nrm = __riscv_vfmacc_vv_f64m1(v_nrm, va, va, vl);
      }
      vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(__riscv_vfmv_v_f_f64m1(0.0, 1), v_nrm, __riscv_vsetvlmax_e64m1());
      nrm = __riscv_vfmv_f_s_f64m1_f64(v_res);
      #else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
      #endif

      R[k][k] = SQRT_FUN(nrm);
      DATA_TYPE inv_Rkk = SCALAR_VAL(1.0) / R[k][k];

      #if defined(__riscv_vector)
      for (i = 0; i < _PB_M; i += __riscv_vsetvlmax_e64m1()) {
        vl = __riscv_vsetvl_e64m1(_PB_M - i);
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][k], vl);
        vfloat64m1_t vq = __riscv_vfmul_vf_f64m1(va, inv_Rkk, vl);
        __riscv_vse64_v_f64m1(&Q[i][k], vq, vl);
      }
      #else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] * inv_Rkk;
      #endif

      for (j = k + 1; j < _PB_N; j++)
	{
	  DATA_TYPE r_kj = SCALAR_VAL(0.0);

	  #if defined(__riscv_vector)
	  vfloat64m1_t v_rkj = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
	  for (i = 0; i < _PB_M; i += __riscv_vsetvlmax_e64m1()) {
	    vl = __riscv_vsetvl_e64m1(_PB_M - i);
	    vfloat64m1_t vq = __riscv_vle64_v_f64m1(&Q[i][k], vl);
	    vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	    v_rkj = __riscv_vfmacc_vv_f64m1(v_rkj, vq, va, vl);
	  }
	  vfloat64m1_t v_res_rkj = __riscv_vfredusum_vs_f64m1_f64m1(__riscv_vfmv_v_f_f64m1(0.0, 1), v_rkj, __riscv_vsetvlmax_e64m1());
	  r_kj = __riscv_vfmv_f_s_f64m1_f64(v_res_rkj);
	  #else
	  for (i = 0; i < _PB_M; i++)
	    r_kj += Q[i][k] * A[i][j];
	  #endif

	  R[k][j] = r_kj;

	  #if defined(__riscv_vector)
	  for (i = 0; i < _PB_M; i += __riscv_vsetvlmax_e64m1()) {
	    vl = __riscv_vsetvl_e64m1(_PB_M - i);
	    vfloat64m1_t vq = __riscv_vle64_v_f64m1(&Q[i][k], vl);
	    vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	    // Corrected: vfmsub_vf(acc, vec, scalar, vl) -> acc - (vec * scalar)
	    // Original: A[i][j] = A[i][j] - Q[i][k] * r_kj
	    vfloat64m1_t vsub = __riscv_vfmsub_vf_f64m1(va, vq, r_kj, vl);
	    __riscv_vse64_v_f64m1(&A[i][j], vsub, vl);
	  }
	  #else
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * r_kj;
	  #endif
	}
    }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
                int k_start = 1;
                int k_end = _PB_N - 1;

                #if defined(__riscv_vector)
                size_t vl;
                vfloat64m1_t v_0125 = __riscv_vfmv_v_f_f64m1(0.125, __riscv_vsetvlmax_e64m1());

                for (k = k_start; k < k_end; ) {
                    vl = __riscv_vsetvl_e64m1(k_end - k);

                    vfloat64m1_t va_ijk = __riscv_vle64_v_f64m1(&A[i][j][k], vl);
                    vfloat64m1_t va_ip1jk = __riscv_vle64_v_f64m1(&A[i+1][j][k], vl);
                    vfloat64m1_t va_im1jk = __riscv_vle64_v_f64m1(&A[i-1][j][k], vl);
                    vfloat64m1_t va_ijp1k = __riscv_vle64_v_f64m1(&A[i][j+1][k], vl);
                    vfloat64m1_t va_ijm1k = __riscv_vle64_v_f64m1(&A[i][j-1][k], vl);
                    vfloat64m1_t va_ijkp1 = __riscv_vle64_v_f64m1(&A[i][j][k+1], vl);
                    vfloat64m1_t va_ijkm1 = __riscv_vle64_v_f64m1(&A[i][j][k-1], vl);

                    vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(va_ip1jk, va_im1jk, vl);
                    v_sum = __riscv_vfadd_vv_f64m1(v_sum, va_ijp1k, vl);
                    v_sum = __riscv_vfadd_vv_f64m1(v_sum, va_ijm1k, vl);
                    v_sum = __riscv_vfadd_vv_f64m1(v_sum, va_ijkp1, vl);
                    v_sum = __riscv_vfadd_vv_f64m1(v_sum, va_ijkm1, vl);

                    vfloat64m1_t v_six_a = __riscv_vfmul_vf_f64m1(va_ijk, 6.0, vl);
                    vfloat64m1_t v_res = __riscv_vfsub_vv_f64m1(v_sum, v_six_a, vl);
                    v_res = __riscv_vfmul_vv_f64m1(v_res, v_0125, vl);
                    v_res = __riscv_vfadd_vv_f64m1(v_res, va_ijk, vl);

                    __riscv_vse64_v_f64m1(&B[i][j][k], v_res, vl);
                    k += vl;
                }
                #else
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                                 + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                                 + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
                #endif
            }
        }
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
               int k_start = 1;
               int k_end = _PB_N - 1;

               #if defined(__riscv_vector)
               size_t vl;
               vfloat64m1_t v_0125 = __riscv_vfmv_v_f_f64m1(0.125, __riscv_vsetvlmax_e64m1());

               for (k = k_start; k < k_end; ) {
                   vl = __riscv_vsetvl_e64m1(k_end - k);

                   vfloat64m1_t vb_ijk = __riscv_vle64_v_f64m1(&B[i][j][k], vl);
                   vfloat64m1_t vb_ip1jk = __riscv_vle64_v_f64m1(&B[i+1][j][k], vl);
                   vfloat64m1_t vb_im1jk = __riscv_vle64_v_f64m1(&B[i-1][j][k], vl);
                   vfloat64m1_t vb_ijp1k = __riscv_vle64_v_f64m1(&B[i][j+1][k], vl);
                   vfloat64m1_t vb_ijm1k = __riscv_vle64_v_f64m1(&B[i][j-1][k], vl);
                   vfloat64m1_t vb_ijkp1 = __riscv_vle64_v_f64m1(&B[i][j][k+1], vl);
                   vfloat64m1_t vb_ijkm1 = __riscv_vle64_v_f64m1(&B[i][j][k-1], vl);

                   vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(vb_ip1jk, vb_im1jk, vl);
                   v_sum = __riscv_vfadd_vv_f64m1(v_sum, vb_ijp1k, vl);
                   v_sum = __riscv_vfadd_vv_f64m1(v_sum, vb_ijm1k, vl);
                   v_sum = __riscv_vfadd_vv_f64m1(v_sum, vb_ijkp1, vl);
                   v_sum = __riscv_vfadd_vv_f64m1(v_sum, vb_ijkm1, vl);

                   vfloat64m1_t v_six_b = __riscv_vfmul_vf_f64m1(vb_ijk, 6.0, vl);
                   vfloat64m1_t v_res = __riscv_vfsub_vv_f64m1(v_sum, v_six_b, vl);
                   v_res = __riscv_vfmul_vv_f64m1(v_res, v_0125, vl);
                   v_res = __riscv_vfadd_vv_f64m1(v_res, vb_ijk, vl);

                   __riscv_vse64_v_f64m1(&A[i][j][k], v_res, vl);
                   k += vl;
               }
               #else
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                                + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                                + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
               #endif
           }
       }
    }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;
  const DATA_TYPE coeff = 0.33333;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == sizeof(float)) {
        vfloat32m1_t v_coeff = __riscv_vfmv_v_f_f32m1(coeff, __riscv_vsetvlmax_e32m1());

        int vl;
        for (i = 1; i < _PB_N - 1; ) {
          vl = __riscv_vsetvl_e32m1(_PB_N - 1 - i);
          vfloat32m1_t va_prev = __riscv_vle32_v_f32m1((float*)&A[i-1], vl);
          vfloat32m1_t va_curr = __riscv_vle32_v_f32m1((float*)&A[i], vl);
          vfloat32m1_t va_next = __riscv_vle32_v_f32m1((float*)&A[i+1], vl);

          vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(va_prev, va_curr, vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, va_next, vl);
          vfloat32m1_t v_res = __riscv_vfmul_vv_f32m1(v_sum, v_coeff, vl);

          __riscv_vse32_v_f32m1((float*)&B[i], v_res, vl);
          i += vl;
        }

        for (i = 1; i < _PB_N - 1; ) {
          vl = __riscv_vsetvl_e32m1(_PB_N - 1 - i);
          vfloat32m1_t vb_prev = __riscv_vle32_v_f32m1((float*)&B[i-1], vl);
          vfloat32m1_t vb_curr = __riscv_vle32_v_f32m1((float*)&B[i], vl);
          vfloat32m1_t vb_next = __riscv_vle32_v_f32m1((float*)&B[i+1], vl);

          vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(vb_prev, vb_curr, vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, vb_next, vl);
          vfloat32m1_t v_res = __riscv_vfmul_vv_f32m1(v_sum, v_coeff, vl);

          __riscv_vse32_v_f32m1((float*)&A[i], v_res, vl);
          i += vl;
        }
      } else {
        for (i = 1; i < _PB_N - 1; i++)
          B[i] = coeff * (A[i-1] + A[i] + A[i + 1]);
        for (i = 1; i < _PB_N - 1; i++)
          A[i] = coeff * (B[i-1] + B[i] + B[i + 1]);
      }
#else
      for (i = 1; i < _PB_N - 1; i++)
        B[i] = coeff * (A[i-1] + A[i] + A[i + 1]);
      for (i = 1; i < _PB_N - 1; i++)
        A[i] = coeff * (B[i-1] + B[i] + B[i + 1]);
#endif
    }
#pragma endscop
}

