#include <riscv_vector.h>
#endif

static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
      {
        int j = 1;
#if defined(__riscv_vector)
        size_t vl;
        // Use double precision vector types as DATA_TYPE is double
        for (; j <= _PB_N - 2; j += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_N - 1 - j);

          vfloat64m1_t v_center = __riscv_vle64_v_f64m1((const double*)&A[i][j], vl);
          vfloat64m1_t v_left   = __riscv_vle64_v_f64m1((const double*)&A[i][j-1], vl);
          vfloat64m1_t v_right  = __riscv_vle64_v_f64m1((const double*)&A[i][j+1], vl);
          vfloat64m1_t v_up     = __riscv_vle64_v_f64m1((const double*)&A[i+1][j], vl);
          vfloat64m1_t v_down   = __riscv_vle64_v_f64m1((const double*)&A[i-1][j], vl);

          vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_center, v_left, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_right, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_up, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_down, vl);

          vfloat64m1_t v_res = __riscv_vfmul_vf_f64m1(v_sum, (double)SCALAR_VAL(0.2), vl);
          __riscv_vse64_v_f64m1((double*)&B[i][j], v_res, vl);
        }
#endif
        for (; j < _PB_N - 1; j++)
          B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
      }

      for (i = 1; i < _PB_N - 1; i++)
      {
        int j = 1;
#if defined(__riscv_vector)
        size_t vl;
        for (; j <= _PB_N - 2; j += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_N - 1 - j);

          vfloat64m1_t v_center = __riscv_vle64_v_f64m1((const double*)&B[i][j], vl);
          vfloat64m1_t v_left   = __riscv_vle64_v_f64m1((const double*)&B[i][j-1], vl);
          vfloat64m1_t v_right  = __riscv_vle64_v_f64m1((const double*)&B[i][j+1], vl);
          vfloat64m1_t v_up     = __riscv_vle64_v_f64m1((const double*)&B[i+1][j], vl);
          vfloat64m1_t v_down   = __riscv_vle64_v_f64m1((const double*)&B[i-1][j], vl);

          vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_center, v_left, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_right, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_up, vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, v_down, vl);

          vfloat64m1_t v_res = __riscv_vfmul_vf_f64m1(v_sum, (double)SCALAR_VAL(0.2), vl);
          __riscv_vse64_v_f64m1((double*)&A[i][j], v_res, vl);
        }
#endif
        for (; j < _PB_N - 1; j++)
          A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
      }
    }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // First inner loop: j < i
    for (j = 0; j < i; j++) {
       DATA_TYPE sum = 0;
       int k_idx = 0;
#if defined(__riscv_vector)
       size_t vlmax = __riscv_vsetvlmax_e64m1();
       vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, 1);
       for (; k_idx <= j - (int)vlmax; k_idx += vlmax) {
           size_t vl = __riscv_vsetvl_e64m1(j - k_idx);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][k_idx], vl);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(&A[k_idx][j], n * sizeof(DATA_TYPE), vl);
           v_sum = __riscv_vfmacc_vv_f64m1(v_sum, va, vk, vl);
       }
       // Use vfredusum.vs: the result is stored in the first element of the destination vector
       // Correct intrinsic name is __riscv_vfredusum_vs_f64m1(v_scalar, v_vector, vl)
       vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vfmv_v_f_f64m1(0.0, 1), v_sum, vlmax);
       sum = __riscv_vfmv_f_s_f64m1_f64(v_res);
#endif
#if !defined(__riscv_vector)
       for (k = 0; k < j; k++) {
          sum += A[i][k] * A[k][j];
       }
#else
       for (; k_idx < j; k_idx++) {
          sum += A[i][k_idx] * A[k_idx][j];
       }
#endif
       A[i][j] -= sum;
       A[i][j] /= A[j][j];
    }

    // Second inner loop: j from i to n-1
    for (j = i; j < _PB_N; j++) {
       DATA_TYPE sum = 0;
       int k_idx = 0;
#if defined(__riscv_vector)
       size_t vlmax = __riscv_vsetvlmax_e64m1();
       vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, 1);
       for (; k_idx <= i - (int)vlmax; k_idx += vlmax) {
           size_t vl = __riscv_vsetvl_e64m1(i - k_idx);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][k_idx], vl);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(&A[k_idx][j], n * sizeof(DATA_TYPE), vl);
           v_sum = __riscv_vfmacc_vv_f64m1(v_sum, va, vk, vl);
       }
       vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vfmv_v_f_f64m1(0.0, 1), v_sum, vlmax);
       sum = __riscv_vfmv_f_s_f64m1_f64(v_res);
#endif
#if !defined(__riscv_vector)
       for (k = 0; k < i; k++) {
          sum += A[i][k] * A[k][j];
       }
#else
       for (; k_idx < i; k_idx++) {
          sum += A[i][k_idx] * A[k_idx][j];
       }
#endif
       A[i][j] -= sum;
    }
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
       w = A[i][j];
       int k_limit = j;
       int k_idx = 0;
#if defined(__riscv_vector)
       size_t vl;
       vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(1, 0.0, 1); 
       for (; k_idx <= k_limit - __riscv_vsetvlmax_e64m1(); k_idx += __riscv_vsetvlmax_e64m1()) {
           vl = __riscv_vsetvlmax_e64m1();
           vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][k_idx]);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(vl, &A[k_idx][j], N * sizeof(DATA_TYPE));
           v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vk);
       }
       if (k_idx < k_limit) {
           vl = __riscv_vsetvl_e64m1(k_limit - k_idx);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][k_idx]);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(vl, &A[k_idx][j], N * sizeof(DATA_TYPE));
           v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vk);
       }
       vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vsetvlmax_e64m1(), v_acc, __riscv_vfmv_v_f_f64m1(1, 0.0, 1));
       w -= __riscv_vfmv_f_s_f64m1(v_res);
#else
       for (k = 0; k < j; k++) {
          w -= A[i][k] * A[k][j];
       }
#endif
       A[i][j] = w / A[j][j];
    }
    for (j = i; j < _PB_N; j++) {
       w = A[i][j];
       int k_limit = i;
       int k_idx = 0;
#if defined(__riscv_vector)
       size_t vl;
       vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(1, 0.0, 1);
       for (; k_idx <= k_limit - __riscv_vsetvlmax_e64m1(); k_idx += __riscv_vsetvlmax_e64m1()) {
           vl = __riscv_vsetvlmax_e64m1();
           vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][k_idx]);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(vl, &A[k_idx][j], N * sizeof(DATA_TYPE));
           v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vk);
       }
       if (k_idx < k_limit) {
           vl = __riscv_vsetvl_e64m1(k_limit - k_idx);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][k_idx]);
           vfloat64m1_t vk = __riscv_vlse64_v_f64m1(vl, &A[k_idx][j], N * sizeof(DATA_TYPE));
           v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vk);
       }
       vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vsetvlmax_e64m1(), v_acc, __riscv_vfmv_v_f_f64m1(1, 0.0, 1));
       w -= __riscv_vfmv_f_s_f64m1(v_res);
#else
       for (k = 0; k < i; k++) {
          w -= A[i][k] * A[k][j];
       }
#endif
       A[i][j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
     int j_limit = i;
     int j_idx = 0;
#if defined(__riscv_vector)
     size_t vl;
     vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(1, 0.0, 1);
     for (; j_idx <= j_limit - __riscv_vsetvlmax_e64m1(); j_idx += __riscv_vsetvlmax_e64m1()) {
         vl = __riscv_vsetvlmax_e64m1();
         vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][j_idx]);
         vfloat64m1_t vy = __riscv_vle64_v_f64m1(vl, &y[j_idx]);
         v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vy);
     }
     if (j_idx < j_limit) {
         vl = __riscv_vsetvl_e64m1(j_limit - j_idx);
         vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][j_idx]);
         vfloat64m1_t vy = __riscv_vle64_v_f64m1(vl, &y[j_idx]);
         v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vy);
     }
     vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vsetvlmax_e64m1(), v_acc, __riscv_vfmv_v_f_f64m1(1, 0.0, 1));
     w -= __riscv_vfmv_f_s_f64m1(v_res);
#else
     for (j = 0; j < i; j++)
        w -= A[i][j] * y[j];
#endif
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
     int j_start = i + 1;
     int j_idx = j_start;
#if defined(__riscv_vector)
     size_t vl;
     vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(1, 0.0, 1);
     int j_limit = _PB_N;
     for (; j_idx <= j_limit - __riscv_vsetvlmax_e64m1(); j_idx += __riscv_vsetvlmax_e64m1()) {
         vl = __riscv_vsetvlmax_e64m1();
         vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][j_idx]);
         vfloat64m1_t vx = __riscv_vle64_v_f64m1(vl, &x[j_idx]);
         v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vx);
     }
     if (j_idx < j_limit) {
         vl = __riscv_vsetvl_e64m1(j_limit - j_idx);
         vfloat64m1_t va = __riscv_vle64_v_f64m1(vl, &A[i][j_idx]);
         vfloat64m1_t vx = __riscv_vle64_v_f64m1(vl, &x[j_idx]);
         v_acc = __riscv_vfmacc_vv_f64m1(vl, v_acc, va, vx);
     }
     vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1(__riscv_vsetvlmax_e64m1(), v_acc, __riscv_vfmv_v_f_f64m1(1, 0.0, 1));
     w -= __riscv_vfmv_f_s_f64m1(v_res);
#else
     for (j = i+1; j < _PB_N; j++)
        w -= A[i][j] * x[j];
#endif
     x[i] = w / A[i][i];
  }
#pragma endscop
}

