static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector)
  // First loop: x1[i] = x1[i] + sum_j(A[i][j] * y_1[j])
  for (i = 0; i < _PB_N; i++) {
    size_t vl;
    vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
    int j_idx = 0;
    while (j_idx < _PB_N) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j_idx);
      vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[i][j_idx], vl);
      vfloat64m1_t v_y1 = __riscv_vle64_v_f64m1(&y_1[j_idx], vl);
      v_acc = __riscv_vfmacc_vv_f64m1(v_acc, v_a, v_y1, vl);
      j_idx += vl;
    }
    // Correct reduction for RISC-V Vector:
    vfloat64m1_t v_init = __riscv_vfmv_v_f_f64m1(0.0, __riscv_vsetvlmax_e64m1());
    vfloat64m1_t v_sum_vec = __riscv_vfredusum_vs_f64m1_f64m1(v_init, v_acc, __riscv_vsetvlmax_e64m1());
    double sum = __riscv_vfmv_f_s_f64m1(v_sum_vec);
    x1[i] += sum;
  }

  // Second loop: x2[i] = x2[i] + sum_j(A[j][i] * y_2[j])
  // Reordered to avoid stride-N access: for j: for i: x2[i] += A[j][i] * y_2[j]
  for (j = 0; j < _PB_N; j++) {
    size_t vl;
    double scalar_y2 = y_2[j];
    int i_idx = 0;
    while (i_idx < _PB_N) {
      vl = __riscv_vsetvl_e64m1(_PB_N - i_idx);
      vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[j][i_idx], vl);
      vfloat64m1_t v_x2 = __riscv_vle64_v_f64m1(&x2[i_idx], vl);
      v_x2 = __riscv_vfmacc_vf_f64m1(v_x2, scalar_y2, v_a, vl);
      __riscv_vse64_v_f64m1(&x2[i_idx], v_x2, vl);
      i_idx += vl;
    }
  }
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#endif
#pragma endscop

}

