static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#pragma scop
 for (i = _PB_N-1; i >= 0; i--) {
  for (j=i+1; j<_PB_N; j++) {
    DATA_TYPE current_max = table[i][j];

    if (j-1>=0) {
      DATA_TYPE val = table[i][j-1];
      if (val > current_max) current_max = val;
    }
    if (i+1<_PB_N) {
      DATA_TYPE val = table[i+1][j];
      if (val > current_max) current_max = val;
    }

    if (j-1>=0 && i+1<_PB_N) {
      DATA_TYPE match_val = table[i+1][j-1];
      if (i < j-1) {
        match_val += match(seq[i], seq[j]);
      }
      if (match_val > current_max) current_max = match_val;
    }

    int k_start = i + 1;
    int k_end = j;
    int len = k_end - k_start;

#if defined(__riscv_vector)
    if (len > 0) {
      size_t vl;
      int k_idx = k_start;

      // Initialize a scalar for reduction
      int32_t scalar_max = (int32_t)current_max;
      vint32m1_t v_max_acc = __riscv_vmv_v_x_i32m1(0, scalar_max, 1);

      for (; (vl = __riscv_vsetvl_e32m1(len - (k_idx - k_start))) > 0; k_idx += vl) {
        vint32m1_t v_ik = __riscv_vle32_v_i32m1(&table[i][k_idx], vl);
        vint32m1_t v_kj = __riscv_vlse32_v_i32m1(&table[k_idx + 1][j], n * sizeof(DATA_TYPE), vl);
        vint32m1_t v_sum = __riscv_vadd_vv_i32m1(v_ik, v_kj, vl);

        // Use vredmax to update the scalar_max
        v_max_acc = __riscv_vredmax_vs_i32m1_i32m1(v_sum, v_max_acc, vl);
        scalar_max = __riscv_vmv_x_s_i32m1_i32(v_max_acc);
      }
      current_max = (DATA_TYPE)scalar_max;
    }
#else
    for (k=i+1; k<j; k++) {
      DATA_TYPE val = table[i][k] + table[k+1][j];
      if (val > current_max) current_max = val;
    }
#endif
    table[i][j] = current_max;
  }
 }
#pragma endscop
}

