static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      DATA_TYPE *row_prev = A[i-1];
      DATA_TYPE *row_curr = A[i];
      DATA_TYPE *row_next = A[i+1];

      int j_start = 1;
      int j_end = _PB_N - 2;

#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == 4) {
        float inv_9 = 1.0f / 9.0f;
        size_t vl;
        for (j = j_start; j <= j_end; ) {
          vl = __riscv_vsetvl_e32m1(j_end - j + 1);

          vfloat32m1_t v_sum = __riscv_vfmv_v_f_f32m1(0.0f, vl);

          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_prev[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_prev[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_prev[j+1], vl), vl);

          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_curr[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_curr[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_curr[j+1], vl), vl);

          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_next[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_next[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f32m1(v_sum, __riscv_vle32_v_f32m1((float*)&row_next[j+1], vl), vl);

          v_sum = __riscv_vfmul_vf_f32m1(v_sum, inv_9, vl);
          __riscv_vse32_v_f32m1((float*)&row_curr[j], v_sum, vl);

          j += vl;
        }
      } else if (sizeof(DATA_TYPE) == 8) {
        double inv_9 = 1.0 / 9.0;
        size_t vl;
        for (j = j_start; j <= j_end; ) {
          vl = __riscv_vsetvl_e64m1(j_end - j + 1);

          vfloat64m1_t v_sum = __riscv_vfmv_v_f_f64m1(0.0, vl);

          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_prev[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_prev[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_prev[j+1], vl), vl);

          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_curr[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_curr[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_curr[j+1], vl), vl);

          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_next[j-1], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_next[j], vl), vl);
          v_sum = __riscv_vfadd_vv_f64m1(v_sum, __riscv_vle64_v_f64m1((double*)&row_next[j+1], vl), vl);

          v_sum = __riscv_vfmul_vf_f64m1(v_sum, inv_9, vl);
          __riscv_vse64_v_f64m1((double*)&row_curr[j], v_sum, vl);

          j += vl;
        }
      } else {
        for (j = j_start; j <= j_end; j++) {
          A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
		     + A[i][j-1] + A[i][j] + A[i][j+1]
		     + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1])/SCALAR_VAL(9.0);
        }
      }
#else
      for (j = j_start; j <= j_end; j++) {
        A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
		   + A[i][j-1] + A[i][j] + A[i][j+1]
		   + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1])/SCALAR_VAL(9.0);
      }
#endif
    }
  }
#pragma endscop
}

