static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
   for (i = 0; i < _PB_M; i++) {
      DATA_TYPE a_ii = A[i][i];

#if defined(__riscv_vector)
      int j_vec = 0;
      size_t vl;
      // The previous error indicated DATA_TYPE is double. 
      // In RVV intrinsics, the scalar argument for f64 operations is simply 'double'.
      for (; j_vec < _PB_N; j_vec += vl) {
        vl = __riscv_vsetvl_e64m1(_PB_N - j_vec);

        vfloat64m1_t v_B_ij = __riscv_vle64_v_f64m1(&B[i][j_vec], vl);
        vfloat64m1_t v_alpha_B_ij = __riscv_vfmul_vf_f64m1(v_B_ij, (double)alpha, vl);
        vfloat64m1_t v_temp2 = __riscv_vfmv_v_f_f64m1(0.0, vl);

        for (k = 0; k < i; k++) {
           DATA_TYPE a_ik = A[i][k];

           vfloat64m1_t v_C_kj = __riscv_vle64_v_f64m1(&C[k][j_vec], vl);
           vfloat64m1_t v_update_C = __riscv_vfmul_vf_f64m1(v_alpha_B_ij, (double)a_ik, vl);
           v_C_kj = __riscv_vfadd_vv_f64m1(v_C_kj, v_update_C, vl);
           __riscv_vse64_v_f64m1(&C[k][j_vec], v_C_kj, vl);

           vfloat64m1_t v_B_kj = __riscv_vle64_v_f64m1(&B[k][j_vec], vl);
           v_temp2 = __riscv_vfmacc_vf_f64m1(v_temp2, (double)a_ik, v_B_kj, vl);
        }

        vfloat64m1_t v_C_ij = __riscv_vle64_v_f64m1(&C[i][j_vec], vl);
        v_C_ij = __riscv_vfmul_vf_f64m1(v_C_ij, (double)beta, vl);

        vfloat64m1_t v_term2 = __riscv_vfmul_vf_f64m1(v_alpha_B_ij, (double)a_ii, vl);
        v_C_ij = __riscv_vfadd_vv_f64m1(v_C_ij, v_term2, vl);

        vfloat64m1_t v_term3 = __riscv_vfmul_vf_f64m1(v_temp2, (double)alpha, vl);
        v_C_ij = __riscv_vfadd_vv_f64m1(v_C_ij, v_term3, vl);

        __riscv_vse64_v_f64m1(&C[i][j_vec], v_C_ij, vl);
      }
#else
      for (j = 0; j < _PB_N; j++) {
        temp2 = 0;
        DATA_TYPE b_ij_val = B[i][j];
        for (k = 0; k < i; k++) {
           C[k][j] += alpha * b_ij_val * A[i][k];
           temp2 += B[k][j] * A[i][k];
        }
        C[i][j] = beta * C[i][j] + alpha * b_ij_val * a_ii + alpha * temp2;
      }
#endif
   }
#pragma endscop
}

