#include <riscv_vector.h>
#endif

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Initialize C[i][0...i] with beta
    int j_init = 0;
#if defined(__riscv_vector)
    if (sizeof(DATA_TYPE) == sizeof(float)) {
      size_t vl_init = __riscv_vsetvl_e32m8(i + 1);
      for (; j_init <= i; j_init += vl_init) {
        vl_init = __riscv_vsetvl_e32m8(i + 1 - j_init);
        vfloat32m8_t v_c = __riscv_vle32_v_f32m8((float*)&C[i][j_init], vl_init);
        v_c = __riscv_vfmul_vf_f32m8(v_c, (float)beta, vl_init);
        __riscv_vse32_v_f32m8((float*)&C[i][j_init], v_c, vl_init);
      }
    } else if (sizeof(DATA_TYPE) == sizeof(double)) {
      size_t vl_init = __riscv_vsetvl_e64m8(i + 1);
      for (; j_init <= i; j_init += vl_init) {
        vl_init = __riscv_vsetvl_e64m8(i + 1 - j_init);
        vfloat64m8_t v_c = __riscv_vle64_v_f64m8((double*)&C[i][j_init], vl_init);
        v_c = __riscv_vfmul_vf_f64m8(v_c, (double)beta, vl_init);
        __riscv_vse64_v_f64m8((double*)&C[i][j_init], v_c, vl_init);
      }
    } else {
      for (j_init = 0; j_init <= i; j_init++) C[i][j_init] *= beta;
    }
#else
    for (j_init = 0; j_init <= i; j_init++) C[i][j_init] *= beta;
#endif

    // Main computation: C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
    // Reorder loops to make the inner loop over j for better vectorization
    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik = A[i][k];
      DATA_TYPE bik = B[i][k];
      DATA_TYPE alpha_aik = alpha * aik;
      DATA_TYPE alpha_bik = alpha * bik;

      int j_idx = 0;
#if defined(__riscv_vector)
      if (sizeof(DATA_TYPE) == sizeof(float)) {
        size_t vlmax = __riscv_vsetvl_e32m8(i + 1);
        for (; j_idx <= i; j_idx += vlmax) {
          size_t vl = __riscv_vsetvl_e32m8(i + 1 - j_idx);
          vfloat32m8_t v_c = __riscv_vle32_v_f32m8((float*)&C[i][j_idx], vl);
          vfloat32m8_t v_ajk_s = __riscv_vlse32_v_f32m8((float*)&A[j_idx][k], _PB_M * sizeof(DATA_TYPE), vl);
          vfloat32m8_t v_bjk_s = __riscv_vlse32_v_f32m8((float*)&B[j_idx][k], _PB_M * sizeof(DATA_TYPE), vl);

          vfloat32m8_t v_term1 = __riscv_vfmul_vf_f32m8(v_ajk_s, (float)alpha_bik, vl);
          vfloat32m8_t v_term2 = __riscv_vfmul_vf_f32m8(v_bjk_s, (float)alpha_aik, vl);
          v_c = __riscv_vfadd_vv_f32m8(v_c, v_term1, vl);
          v_c = __riscv_vfadd_vv_f32m8(v_c, v_term2, vl);
          __riscv_vse32_v_f32m8((float*)&C[i][j_idx], v_c, vl);
        }
      } else if (sizeof(DATA_TYPE) == sizeof(double)) {
        size_t vlmax = __riscv_vsetvl_e64m8(i + 1);
        for (; j_idx <= i; j_idx += vlmax) {
          size_t vl = __riscv_vsetvl_e64m8(i + 1 - j_idx);
          vfloat64m8_t v_c = __riscv_vle64_v_f64m8((double*)&C[i][j_idx], vl);
          vfloat64m8_t v_ajk_s = __riscv_vlse64_v_f64m8((double*)&A[j_idx][k], _PB_M * sizeof(DATA_TYPE), vl);
          vfloat64m8_t v_bjk_s = __riscv_vlse64_v_f64m8((double*)&B[j_idx][k], _PB_M * sizeof(DATA_TYPE), vl);

          vfloat64m8_t v_term1 = __riscv_vfmul_vf_f64m8(v_ajk_s, (double)alpha_bik, vl);
          vfloat64m8_t v_term2 = __riscv_vfmul_vf_f64m8(v_bjk_s, (double)alpha_aik, vl);
          v_c = __riscv_vfadd_vv_f64m8(v_c, v_term1, vl);
          v_c = __riscv_vfadd_vv_f64m8(v_c, v_term2, vl);
          __riscv_vse64_v_f64m8((double*)&C[i][j_idx], v_c, vl);
        }
      } else {
        for (; j_idx <= i; j_idx++) {
          C[i][j_idx] += A[j_idx][k] * alpha_bik + B[j_idx][k] * alpha_aik;
        }
      }
#else
      for (; j_idx <= i; j_idx++) {
        C[i][j_idx] += A[j_idx][k] * alpha_bik + B[j_idx][k] * alpha_aik;
      }
#endif
    }
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Initialize C[i][j] = C[i][j] * beta for j = 0 to i
    if (__riscv_vector) {
      int j_vec = 0;
      size_t vl;
      vfloat64m1_t v_beta = __riscv_vfmv_v_f_f64m1(beta, __riscv_vsetvlmax_e64m1());
      for (; (j_vec <= i); j_vec += vl) {
        vl = __riscv_vsetvl_e64m1(i - j_vec + 1);
        vfloat64m1_t v_c = __riscv_vle64_v_f64m1(&C[i][j_vec], vl);
        v_c = __riscv_vfmul_vv_f64m1(v_c, v_beta, vl);
        __riscv_vse64_v_f64m1(&C[i][j_vec], v_c, vl);
      }
    } else {
      for (j = 0; j <= i; j++)
        C[i][j] *= beta;
    }

    // Compute C[i][j] += alpha * A[i][k] * A[j][k]
    // To improve performance, we can hoist the loading of C[i][j] 
    // and accumulate in registers if the vector length allows, 
    // but since we iterate over k, we can't easily keep C[i][j] in registers 
    // across the k-loop without changing the loop order or using a large register file.
    // However, we can optimize the inner loop by reducing memory traffic.

    if (__riscv_vector) {
      // We process the k-loop. For each k, we update the vector C[i][0...i].
      for (k = 0; k < _PB_M; k++) {
        DATA_TYPE alpha_aik = alpha * A[i][k];
        vfloat64m1_t v_alpha_aik = __riscv_vfmv_v_f_f64m1(alpha_aik, __riscv_vsetvlmax_e64m1());

        int j_vec = 0;
        size_t vl;
        for (; (j_vec <= i); j_vec += vl) {
          vl = __riscv_vsetvl_e64m1(i - j_vec + 1);
          // Strided load for A[j][k]
          vfloat64m1_t v_ajk = __riscv_vlse64_v_f64m1(&A[j_vec][k], _PB_M * sizeof(DATA_TYPE), vl);
          vfloat64m1_t v_cij = __riscv_vle64_v_f64m1(&C[i][j_vec], vl);
          v_cij = __riscv_vfmacc_vv_f64m1(v_cij, v_alpha_aik, v_ajk, vl);
          __riscv_vse64_v_f64m1(&C[i][j_vec], v_cij, vl);
        }
      }
    } else {
      for (k = 0; k < _PB_M; k++) {
        DATA_TYPE alpha_aik = alpha * A[i][k];
        for (j = 0; j <= i; j++)
          C[i][j] += alpha_aik * A[j][k];
      }
    }
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE sum = b[i];

      #if defined(__riscv_vector)
      // To ensure correctness and avoid potential alignment or reduction issues 
      // that caused the runtime failure (status 132 is often SIGILL or SIGSEGV),
      // we use a more robust vectorization approach.
      int vl;
      vfloat64m1_t v_acc = __riscv_vfmv_v_f_f64m1(0.0, 1);

      for (j = 0; j < i; ) {
        vl = __riscv_vsetvl_e64m1(i - j);
        vfloat64m1_t v_L = __riscv_vle64_v_f64m1(&L[i][j], vl);
        vfloat64m1_t v_x = __riscv_vle64_v_f64m1(&x[j], vl);
        v_acc = __riscv_vfmacc_vv_f64m1(v_acc, v_L, v_x, vl);
        j += vl;
      }

      // Reduction: sum the elements of v_acc
      // Using a scalar vector for the reduction target
      vfloat64m1_t v_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
      vfloat64m1_t v_res = __riscv_vfredusum_vs_f64m1_f64m1(v_acc, v_zero, __riscv_vsetvl_e64m1(0));
      sum -= __riscv_vfmv_f_s_f64m1_f64(v_res);
      #else
      for (j = 0; j < i; j++)
        sum -= L[i][j] * x[j];
      #endif

      x[i] = sum / L[i][i];
    }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    // Reorder loops to (i, k, j) to allow vectorization of the innermost loop j
    for (k = i + 1; k < _PB_M; k++) {
      DATA_TYPE aik = A[k][i];

      #if defined(__riscv_vector)
      int j_vec = 0;
      size_t vl;
      // Assuming DATA_TYPE is float for RVV implementation
      vfloat32m1_t v_aik = __riscv_vfmv_v_f_f32m1((float)aik, 0); 

      for (j_vec = 0; j_vec < _PB_N; ) {
        vl = __riscv_vsetvl_e32m1(_PB_N - j_vec);
        vfloat32m1_t v_bkj = __riscv_vle32_v_f32m1((float*)&B[k][j_vec], vl);
        vfloat32m1_t v_bij = __riscv_vle32_v_f32m1((float*)&B[i][j_vec], vl);
        vfloat32m1_t v_res = __riscv_vfmacc_vv_f32m1(v_bij, v_aik, v_bkj, vl);
        __riscv_vse32_v_f32m1((float*)&B[i][j_vec], v_res, vl);
        j_vec += vl;
      }
      #else
      for (j = 0; j < _PB_N; j++) {
        B[i][j] += aik * B[k][j];
      }
      #endif
    }

    #if defined(__riscv_vector)
    int j_vec = 0;
    vfloat32m1_t v_alpha = __riscv_vfmv_v_f_f32m1((float)alpha, 0);
    for (j_vec = 0; j_vec < _PB_N; ) {
      size_t vl = __riscv_vsetvl_e32m1(_PB_N - j_vec);
      vfloat32m1_t v_bij = __riscv_vle32_v_f32m1((float*)&B[i][j_vec], vl);
      vfloat32m1_t v_res = __riscv_vfmul_vv_f32m1(v_bij, v_alpha, vl);
      __riscv_vse32_v_f32m1((float*)&B[i][j_vec], v_res, vl);
      j_vec += vl;
    }
    #else
    for (j = 0; j < _PB_N; j++) {
      B[i][j] = alpha * B[i][j];
    }
    #endif
  }
#pragma endscop
}
